levels.solution:
# 1. 走る・回る道具
def go(m):
    motor(1.0, 1.0)
    wait(m / 1.1)
    stop()

def turn(deg):
    if deg > 0:
        motor(0.25, -0.25)
    else:
        motor(-0.25, 0.25)
    wait(abs(deg) / 195)
    stop()

# 2. ROUTE の順に走る（最後の組だけ手前で止まる）
for i in range(len(ROUTE)):
    a, m = ROUTE[i]
    if i == len(ROUTE) - 1:
        m = m - 0.45    # 最後はコーンの中心まで。半径・機体・すべりの分だけ手前
    turn(a)
    go(m)
